    public static int translatedCases() { return CASES.size(); }
    public static String title(String id, String fallback) { return field(id, fallback, 0); }
    public static String instructions(String id, String fallback) { return field(id, fallback, 1); }
    public static String expected(String id, String fallback) { return field(id, fallback, 2); }
    private static String field(String id, String fallback, int index) {
        String[] values = CASES.get(id);
        return values == null ? fallback : values[index];
    }
    public static String status(String machine) {
        switch (machine == null ? "" : machine) {
            case "PASS": return "نجح تلقائيًا";
            case "USER_PASS": return "نجح بمراجعة المالك";
            case "FAIL": return "فشل الاختبار";
            case "USER_FAIL": return "فشل وفق ملاحظة المالك";
            case "EVIDENCE_READY": return "الدليل جاهز للمراجعة (ليس نجاحًا نهائيًا)";
            case "NEEDS_INPUT": return "يحتاج إدخالًا أو تجربة منك";
            case "NEEDS_SCREENSHOT": return "يحتاج صورة من الاختبار";
            case "PENDING_VISUAL": return "ينتظر مراجعة الصورة";
            case "BLOCKED": return "متعذّر التنفيذ؛ راجع الدليل";
            default: return "لم يُنفّذ بعد";
        }
    }
